// Programming language learning paths: Java, Python and C.
// Each lesson: explanation, syntax, example code, applications, interview Q&A and practice tasks.
// Tuple format: [slug, title, explanation, syntax, exampleCode, applications[], [[q, a], ...], practice[]]

const JAVA = [
  ['intro', 'Introduction to Java', 'Java is a statically typed, object-oriented language that compiles to bytecode and runs on the Java Virtual Machine (JVM), which makes it "write once, run anywhere". Every Java program has at least one class, and execution starts at public static void main(String[] args). The JDK contains the compiler (javac), the JRE contains the JVM and libraries needed to run programs.', 'public class Main {\n    public static void main(String[] args) {\n        // statements\n    }\n}', 'public class Main {\n    public static void main(String[] args) {\n        System.out.println("Hello, BrainBridge!");\n    }\n}', ['Enterprise backends (Spring Boot)', 'Android apps', 'Big data tools (Hadoop, Kafka)'], [['What is the difference between JDK, JRE and JVM?', 'JVM runs bytecode; JRE = JVM + standard libraries to run programs; JDK = JRE + development tools like javac and javadoc.'], ['Why is Java platform-independent?', 'The compiler produces bytecode, not machine code; any platform with a JVM can execute that bytecode.']], ['Print your name and college on two lines.', 'Compile with javac and run with java from the terminal.']],
  ['variables', 'Variables and Data Types', 'A variable is a named memory location with a fixed type. Java has 8 primitive types (byte, short, int, long, float, double, char, boolean) and reference types (String, arrays, objects). Primitives store values directly; references store the address of an object. Local variables must be initialised before use.', 'type name = value;\nfinal type CONSTANT = value;  // cannot be reassigned', 'public class Main {\n    public static void main(String[] args) {\n        int age = 20;\n        double cgpa = 8.45;\n        char grade = \'A\';\n        boolean placed = false;\n        String name = "Asha";\n        long population = 1_400_000_000L;\n        System.out.println(name + " is " + age + ", CGPA " + cgpa);\n        int x = (int) 9.8;   // explicit casting -> 9\n        System.out.println(x);\n    }\n}', ['Storing user input', 'Configuration constants', 'Counters and accumulators'], [['What is the default value of an int field and a local int?', 'Instance/static int fields default to 0; local variables have no default and must be initialised.'], ['What is the size of int, long and char in Java?', 'int 4 bytes, long 8 bytes, char 2 bytes (UTF-16).'], ['Difference between widening and narrowing conversion?', 'Widening (int → long) is automatic; narrowing (double → int) needs an explicit cast and may lose data.']], ['Declare variables for a student record and print them.', 'Convert Celsius to Fahrenheit using double arithmetic.']],
  ['operators', 'Operators', 'Operators perform operations on variables: arithmetic (+ - * / %), relational (== != > < >= <=), logical (&& || !), assignment (= += -=), increment/decrement (++ --), bitwise (& | ^ ~ << >>) and the ternary operator (cond ? a : b). Integer division truncates towards zero. && and || short-circuit.', 'result = a + b;\nboolean ok = (a > b) && (b != 0);\nint max = (a > b) ? a : b;', 'public class Main {\n    public static void main(String[] args) {\n        int a = 17, b = 5;\n        System.out.println(a / b);   // 3\n        System.out.println(a % b);   // 2\n        System.out.println(a / (double) b); // 3.4\n        int i = 5;\n        int j = i++ + ++i;           // 5 + 7 = 12\n        System.out.println(j);\n        System.out.println(a > b ? "a" : "b");\n    }\n}', ['Calculations and validations', 'Bit flags', 'Conditional expressions'], [['What is the difference between i++ and ++i?', 'i++ returns the old value then increments; ++i increments first and returns the new value.'], ['What is short-circuit evaluation?', 'In a && b, b is not evaluated if a is false; in a || b, b is not evaluated if a is true.']], ['Check if a number is even using % and using & 1.', 'Swap two numbers without a temporary variable.']],
  ['conditions', 'Conditional Statements', 'Conditionals choose which code runs: if, if-else, else-if ladders and switch. Since Java 14, switch expressions with arrows return values. Conditions must be boolean — Java does not treat 0 as false.', 'if (condition) { ... } else if (other) { ... } else { ... }\nswitch (day) { case 1 -> ...; default -> ...; }', 'public class Main {\n    public static void main(String[] args) {\n        int marks = 78;\n        if (marks >= 90) System.out.println("A");\n        else if (marks >= 75) System.out.println("B");\n        else System.out.println("C");\n\n        int day = 3;\n        String name = switch (day) {\n            case 1 -> "Mon";\n            case 2 -> "Tue";\n            case 3 -> "Wed";\n            default -> "Other";\n        };\n        System.out.println(name);\n    }\n}', ['Grading systems', 'Menu-driven programs', 'Input validation'], [['Can switch work with Strings in Java?', 'Yes, since Java 7 switch supports String (and enums, int, char, byte, short and wrappers).'], ['What happens if you forget break in a classic switch?', 'Execution falls through to the next case until a break or the end.']], ['Find the largest of three numbers.', 'Check whether a year is a leap year.']],
  ['loops', 'Loops', 'Loops repeat code: for (known count), while (condition checked first), do-while (runs at least once) and the enhanced for-each loop for arrays/collections. break exits the loop; continue skips to the next iteration. Labelled break can exit nested loops.', 'for (int i = 0; i < n; i++) { ... }\nwhile (cond) { ... }\ndo { ... } while (cond);\nfor (int x : arr) { ... }', 'public class Main {\n    public static void main(String[] args) {\n        int sum = 0;\n        for (int i = 1; i <= 10; i++) sum += i;\n        System.out.println("Sum = " + sum);\n\n        int n = 12345, rev = 0;\n        while (n > 0) { rev = rev * 10 + n % 10; n /= 10; }\n        System.out.println("Reverse = " + rev);\n\n        for (int i = 1; i <= 4; i++) {\n            for (int j = 1; j <= i; j++) System.out.print("* ");\n            System.out.println();\n        }\n    }\n}', ['Processing lists of data', 'Pattern printing', 'Game loops'], [['Difference between while and do-while?', 'while checks the condition before the first iteration; do-while runs the body once before checking.'], ['How do you break out of nested loops?', 'Use a labelled break (outer: for ... break outer;) or a flag variable.']], ['Print the multiplication table of n.', 'Print all prime numbers up to 100.', 'Print a right-angled triangle pattern.']],
  ['arrays', 'Arrays', 'An array is a fixed-size, indexed collection of elements of the same type, stored contiguously. Indices start at 0; accessing an invalid index throws ArrayIndexOutOfBoundsException. Arrays are objects, so they have a length field. 2D arrays are arrays of arrays.', 'int[] a = new int[5];\nint[] b = {1, 2, 3};\nint[][] grid = new int[3][4];', 'import java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[] marks = {72, 88, 95, 60};\n        int max = marks[0];\n        for (int m : marks) max = Math.max(max, m);\n        System.out.println("Max = " + max);\n        Arrays.sort(marks);\n        System.out.println(Arrays.toString(marks));\n        int[][] grid = {{1, 2}, {3, 4}};\n        System.out.println(grid[1][0]); // 3\n    }\n}', ['Storing marks, prices, sensor readings', 'Matrices', 'Foundation for most DSA problems'], [['Why do arrays start at index 0?', 'The index is an offset from the base address; the first element is at offset 0.'], ['How are arrays different from ArrayList?', 'Arrays have fixed size and can hold primitives; ArrayList resizes dynamically and holds objects only.']], ['Find the second largest element.', 'Reverse an array in place.', 'Add two matrices.']],
  ['strings', 'Strings', 'String is an immutable sequence of characters. Every modification creates a new object, so use StringBuilder for repeated concatenation in loops. Compare contents with equals(), not ==. String literals are stored in the String Constant Pool.', 'String s = "hello";\ns.length(); s.charAt(0); s.substring(1, 3);\ns.equals(t); s.toUpperCase(); s.split(" ");\nStringBuilder sb = new StringBuilder();', 'public class Main {\n    public static void main(String[] args) {\n        String s = "BrainBridge";\n        System.out.println(s.length() + " " + s.toUpperCase());\n        System.out.println(s.indexOf("Bridge"));\n        String a = new String("hi"), b = "hi";\n        System.out.println(a == b);       // false (different objects)\n        System.out.println(a.equals(b));  // true\n        StringBuilder sb = new StringBuilder(s).reverse();\n        System.out.println(sb);\n    }\n}', ['Text processing', 'Parsing input', 'Building responses'], [['Why are Strings immutable in Java?', 'For security, thread safety, caching of hash codes and safe sharing in the string pool.'], ['String vs StringBuilder vs StringBuffer?', 'String is immutable; StringBuilder is mutable and fast (not synchronised); StringBuffer is mutable and synchronised.']], ['Check if a string is a palindrome.', 'Count vowels in a sentence.', 'Reverse each word in a sentence.']],
  ['methods', 'Methods', 'Methods group reusable code. A method has a return type, name, parameters and body. Java is always pass-by-value: for objects, the reference is copied, so the method can modify the object but not reassign the caller\'s variable. Overloading = same name, different parameter lists. Recursion = a method calling itself.', 'static returnType name(type param) {\n    return value;\n}', 'public class Main {\n    static int square(int x) { return x * x; }\n    static double square(double x) { return x * x; }   // overloading\n    static long factorial(int n) { return n <= 1 ? 1 : n * factorial(n - 1); }\n\n    public static void main(String[] args) {\n        System.out.println(square(5));\n        System.out.println(square(2.5));\n        System.out.println(factorial(10));\n    }\n}', ['Code reuse', 'Breaking problems into steps', 'Recursive algorithms'], [['Is Java pass-by-value or pass-by-reference?', 'Always pass-by-value. For objects, the value passed is a copy of the reference.'], ['What is method overloading?', 'Multiple methods with the same name but different parameter types/counts, resolved at compile time.']], ['Write isPrime(int n).', 'Write a method that returns the GCD of two numbers.']],
  ['classes-objects', 'Classes and Objects', 'A class is a blueprint that defines fields (state) and methods (behaviour). An object is an instance created with new, stored on the heap. The this keyword refers to the current object. Static members belong to the class, not to individual objects.', 'class Student {\n    String name;\n    int marks;\n    void show() { ... }\n}\nStudent s = new Student();', 'class Student {\n    String name;\n    int marks;\n    static int count = 0;\n    Student(String name, int marks) { this.name = name; this.marks = marks; count++; }\n    boolean passed() { return marks >= 40; }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Student a = new Student("Asha", 82);\n        Student b = new Student("Dev", 35);\n        System.out.println(a.name + " passed: " + a.passed());\n        System.out.println(b.name + " passed: " + b.passed());\n        System.out.println("Students created: " + Student.count);\n    }\n}', ['Modelling real-world entities', 'Domain models in applications'], [['What is the difference between a class and an object?', 'A class is a template; an object is a concrete instance with its own state in memory.'], ['What is a static variable?', 'A variable shared by all instances of the class, stored once per class.']], ['Create a BankAccount class with deposit and withdraw.', 'Create a Rectangle class with area() and perimeter().']],
  ['constructors', 'Constructors', 'A constructor initialises a new object. It has the same name as the class and no return type. If you write none, Java adds a default no-argument constructor. Constructors can be overloaded and can call each other with this(...). The first statement can call the parent constructor with super(...).', 'ClassName() { ... }\nClassName(type a) { this(); ... }', 'class Point {\n    int x, y;\n    Point() { this(0, 0); }                 // constructor chaining\n    Point(int x, int y) { this.x = x; this.y = y; }\n    public String toString() { return "(" + x + ", " + y + ")"; }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println(new Point());\n        System.out.println(new Point(3, 4));\n    }\n}', ['Ensuring objects start in a valid state', 'Dependency injection'], [['Can a constructor be private?', 'Yes — used in the Singleton pattern and utility classes to prevent outside instantiation.'], ['Difference between constructor and method?', 'Constructors have no return type, share the class name, and run automatically on object creation.']], ['Create an Employee class with overloaded constructors.', 'Implement a copy constructor.']],
  ['inheritance', 'Inheritance', 'Inheritance lets a class (subclass) reuse and extend another class (superclass) using extends. Java supports single, multilevel and hierarchical inheritance with classes, but not multiple inheritance of classes (to avoid the diamond problem) — interfaces solve that. super accesses parent members.', 'class Child extends Parent { ... }', 'class Vehicle {\n    String brand;\n    Vehicle(String brand) { this.brand = brand; }\n    void start() { System.out.println(brand + " vehicle starting"); }\n}\nclass Car extends Vehicle {\n    int seats;\n    Car(String brand, int seats) { super(brand); this.seats = seats; }\n    @Override void start() { super.start(); System.out.println("Car with " + seats + " seats ready"); }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        new Car("Tata", 5).start();\n    }\n}', ['Code reuse', 'Class hierarchies in frameworks'], [['Why does Java not support multiple inheritance with classes?', 'To avoid ambiguity (the diamond problem) when two parents have the same method.'], ['What does super() do?', 'Calls the parent class constructor; it must be the first statement in the child constructor.']], ['Create Shape → Circle/Square hierarchy.', 'Model Person → Student → GraduateStudent.']],
  ['polymorphism', 'Polymorphism', 'Polymorphism means one interface, many forms. Compile-time polymorphism = method overloading. Runtime polymorphism = method overriding, where a parent reference points to a child object and the overridden method is chosen at runtime (dynamic method dispatch).', 'Parent p = new Child();\np.method();  // Child\'s version runs', 'abstract class Shape { abstract double area(); }\nclass Circle extends Shape { double r; Circle(double r) { this.r = r; } double area() { return Math.PI * r * r; } }\nclass Square extends Shape { double s; Square(double s) { this.s = s; } double area() { return s * s; } }\n\npublic class Main {\n    public static void main(String[] args) {\n        Shape[] shapes = { new Circle(1), new Square(2) };\n        for (Shape sh : shapes) System.out.printf("%.2f%n", sh.area());\n    }\n}', ['Plugin architectures', 'Writing code against interfaces'], [['Overloading vs overriding?', 'Overloading: same name, different parameters, resolved at compile time. Overriding: same signature in subclass, resolved at runtime.'], ['Can static methods be overridden?', 'No. Static methods are hidden, not overridden, because they are bound at compile time.']], ['Create an Animal hierarchy where each animal makes a different sound.', 'Compute total salary of different employee types using a common method.']],
  ['encapsulation', 'Encapsulation', 'Encapsulation bundles data and methods together and restricts direct access to the data using access modifiers (private, default, protected, public). Fields are made private and exposed through getters and setters that can validate values.', 'private type field;\npublic type getField() { return field; }\npublic void setField(type v) { /* validate */ field = v; }', 'class Account {\n    private double balance;\n    public double getBalance() { return balance; }\n    public void deposit(double amt) {\n        if (amt <= 0) throw new IllegalArgumentException("Amount must be positive");\n        balance += amt;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Account a = new Account();\n        a.deposit(500);\n        System.out.println(a.getBalance());\n    }\n}', ['Protecting invariants (balance never negative)', 'Hiding implementation details'], [['What are the access modifiers in Java?', 'private (class only), default (package), protected (package + subclasses), public (everywhere).'], ['How is encapsulation different from abstraction?', 'Encapsulation hides data via access control; abstraction hides implementation complexity behind a simple interface.']], ['Create an encapsulated Student class with validated marks (0-100).']],
  ['abstraction', 'Abstraction', 'Abstraction shows only essential features and hides implementation details. In Java it is achieved with abstract classes (can have state, constructors and concrete methods) and interfaces (contracts). An abstract class cannot be instantiated.', 'abstract class Payment {\n    abstract void pay(double amount);\n    void receipt() { ... }\n}', 'abstract class Payment {\n    abstract void pay(double amount);\n    void receipt(double amount) { System.out.println("Paid " + amount); }\n}\nclass UpiPayment extends Payment {\n    void pay(double amount) { System.out.println("Paying via UPI"); receipt(amount); }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Payment p = new UpiPayment();\n        p.pay(250);\n    }\n}', ['Frameworks defining templates', 'Payment gateways, drivers'], [['Abstract class vs interface?', 'Abstract classes can have state, constructors and any access modifiers; a class can extend only one. Interfaces define contracts and a class can implement many.'], ['Can an abstract class have a constructor?', 'Yes, it runs when a subclass object is created.']], ['Design an abstract Employee class with calculateSalary().']],
  ['interfaces', 'Interfaces', 'An interface is a contract of methods a class must implement. Fields are implicitly public static final. Since Java 8, interfaces can have default and static methods; since Java 9, private methods. A class can implement multiple interfaces. Functional interfaces (one abstract method) work with lambdas.', 'interface Drawable { void draw(); }\nclass Circle implements Drawable { public void draw() { ... } }', 'import java.util.*;\n\ninterface Greeter { String greet(String name); }\n\npublic class Main {\n    public static void main(String[] args) {\n        Greeter g = name -> "Hello, " + name;   // lambda for a functional interface\n        System.out.println(g.greet("Dev"));\n        List<String> names = new ArrayList<>(List.of("zara", "amit", "kiran"));\n        names.sort(Comparator.naturalOrder());\n        System.out.println(names);\n    }\n}', ['Loose coupling', 'Callbacks and lambdas', 'Collections framework (List, Map)'], [['Can an interface have a method body?', 'Yes: default and static methods (Java 8+) and private methods (Java 9+).'], ['What is a functional interface?', 'An interface with exactly one abstract method, e.g. Runnable, Comparator; usable with lambdas.']], ['Create a Sortable interface and implement it for two classes.']],
  ['exceptions', 'Exception Handling', 'Exceptions signal errors at runtime. Checked exceptions (IOException) must be handled or declared with throws; unchecked exceptions (RuntimeException, e.g. NullPointerException) need not be. Use try-catch-finally, multi-catch and try-with-resources for automatic closing.', 'try { ... }\ncatch (IOException | NumberFormatException e) { ... }\nfinally { ... }\nthrow new IllegalArgumentException("msg");', 'public class Main {\n    static int parse(String s) {\n        try {\n            return Integer.parseInt(s);\n        } catch (NumberFormatException e) {\n            System.out.println("Invalid number: " + s);\n            return 0;\n        } finally {\n            System.out.println("parse finished");\n        }\n    }\n    public static void main(String[] args) {\n        System.out.println(parse("42"));\n        System.out.println(parse("4x2"));\n    }\n}', ['Robust input handling', 'Resource cleanup', 'API error responses'], [['Checked vs unchecked exceptions?', 'Checked are verified at compile time and must be handled or declared; unchecked (RuntimeException subclasses) are not.'], ['Does finally run if there is a return in try?', 'Yes, finally runs before the method returns (except in cases like System.exit).'], ['throw vs throws?', 'throw raises an exception object; throws declares exceptions a method may propagate.']], ['Read two numbers and handle division by zero.', 'Create a custom InsufficientBalanceException.']],
  ['collections', 'Collections Framework', 'The Collections Framework provides data structures: List (ArrayList, LinkedList), Set (HashSet, LinkedHashSet, TreeSet), Map (HashMap, LinkedHashMap, TreeMap), Queue/Deque (ArrayDeque, PriorityQueue). Choose based on ordering, duplicates and time complexity.', 'List<Integer> list = new ArrayList<>();\nMap<String, Integer> map = new HashMap<>();\nSet<String> set = new HashSet<>();\nDeque<Integer> stack = new ArrayDeque<>();', 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        String text = "to be or not to be";\n        Map<String, Integer> freq = new TreeMap<>();\n        for (String w : text.split(" ")) freq.put(w, freq.getOrDefault(w, 0) + 1);\n        System.out.println(freq);              // {be=2, not=1, or=1, to=2}\n        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());\n        pq.addAll(List.of(5, 1, 9, 3));\n        System.out.println(pq.poll());         // 9\n    }\n}', ['Word counts, caches, leaderboards', 'Almost every Java backend'], [['How does HashMap work internally?', 'It hashes the key to a bucket index; collisions are stored in a linked list that becomes a balanced tree when large (Java 8+). Average O(1) get/put.'], ['ArrayList vs LinkedList?', 'ArrayList: O(1) random access, costly middle inserts. LinkedList: O(1) insert at ends/known node, O(n) access.'], ['HashSet vs TreeSet?', 'HashSet is unordered with O(1) operations; TreeSet keeps elements sorted with O(log n).']], ['Count character frequencies using HashMap.', 'Remove duplicates from a list while preserving order.']],
  ['file-handling', 'File Handling', 'Java reads and writes files using java.io (FileReader, BufferedReader, FileWriter) and the newer java.nio.file API (Files, Paths). Always close resources — try-with-resources does this automatically.', 'try (BufferedReader br = new BufferedReader(new FileReader("in.txt"))) { ... }\nFiles.writeString(Path.of("out.txt"), text);', 'import java.io.*;\nimport java.nio.file.*;\nimport java.util.List;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        Path p = Path.of("notes.txt");\n        Files.write(p, List.of("line one", "line two"));\n        try (BufferedReader br = Files.newBufferedReader(p)) {\n            String line;\n            while ((line = br.readLine()) != null) System.out.println(line.toUpperCase());\n        }\n    }\n}', ['Logs, reports, CSV import/export', 'Configuration files'], [['What is try-with-resources?', 'A try statement that automatically closes any AutoCloseable resource declared in it.'], ['Byte streams vs character streams?', 'Byte streams (InputStream) handle raw bytes; character streams (Reader/Writer) handle text with encoding.']], ['Count lines and words in a text file.', 'Copy one file to another.']],
  ['multithreading', 'Multithreading Basics', 'A thread is an independent path of execution. Create threads by extending Thread or implementing Runnable (preferred), or use ExecutorService. Shared data needs synchronisation (synchronized, locks, atomic classes) to avoid race conditions.', 'Thread t = new Thread(() -> { ... });\nt.start();\nt.join();\nsynchronized void increment() { ... }', 'import java.util.concurrent.atomic.AtomicInteger;\n\npublic class Main {\n    public static void main(String[] args) throws InterruptedException {\n        AtomicInteger counter = new AtomicInteger();\n        Runnable task = () -> { for (int i = 0; i < 1000; i++) counter.incrementAndGet(); };\n        Thread t1 = new Thread(task), t2 = new Thread(task);\n        t1.start(); t2.start();\n        t1.join(); t2.join();\n        System.out.println(counter.get()); // always 2000\n    }\n}', ['Web servers handling many requests', 'Background jobs', 'Parallel computation'], [['start() vs run()?', 'start() creates a new thread that calls run(); calling run() directly runs on the current thread.'], ['What is a race condition?', 'When the result depends on the unpredictable order of threads accessing shared data.'], ['What is a deadlock?', 'Two or more threads wait forever for locks held by each other.']], ['Print even and odd numbers alternately with two threads.']],
];

const PYTHON = [
  ['intro', 'Introduction to Python', 'Python is a high-level, dynamically typed, interpreted language known for readable syntax. Indentation defines code blocks. It is widely used for automation, web backends, data analysis and machine learning.', 'print("text")\n# comments start with #', 'print("Hello, BrainBridge!")\nname = "Asha"\nprint(f"Welcome, {name}")', ['Data science and ML', 'Scripting and automation', 'Web backends (Django, Flask, FastAPI)'], [['Is Python compiled or interpreted?', 'CPython compiles source to bytecode which the Python virtual machine interprets.'], ['What is PEP 8?', 'The official style guide for Python code (naming, indentation, line length).']], ['Print a greeting using an f-string.', 'Run a .py file from the terminal.']],
  ['variables', 'Variables and Data Types', 'Variables are names bound to objects; the type belongs to the object, not the name (dynamic typing). Core types: int (unbounded), float, complex, bool, str, NoneType, plus collections list, tuple, set, dict. Use type() to inspect and int()/float()/str() to convert.', 'x = 10\nname = "Dev"\nprice = 99.5\nis_ok = True', 'age = 21\ncgpa = 8.7\nname = "Asha"\nplaced = False\nbig = 2 ** 100          # Python ints have no fixed size\nprint(type(age), type(cgpa), type(name))\nprint(int("42") + 1, float("3.5"), str(10) + "0")\na, b = 1, 2\na, b = b, a              # swap\nprint(a, b, big)', ['Storing data of any type', 'Quick scripting'], [['Is Python statically typed?', 'No, it is dynamically typed: types are checked at runtime. Type hints are optional annotations.'], ['Mutable vs immutable types?', 'Mutable: list, dict, set. Immutable: int, float, str, tuple, frozenset.']], ['Swap two variables without a temp.', 'Convert input strings to numbers and add them.']],
  ['operators', 'Operators', 'Python operators: arithmetic (+ - * / // % **), comparison, logical (and or not), membership (in, not in), identity (is, is not) and bitwise. / always returns float; // is floor division. Comparisons can be chained (1 < x < 10).', 'a // b   # floor division\na ** b   # power\nx in items\na is b   # same object', 'a, b = 17, 5\nprint(a / b, a // b, a % b, a ** 2)\nprint(-7 // 2)            # -4 (floors towards negative infinity)\nx = 7\nprint(1 < x < 10)          # chained comparison\nprint("py" in "python")\nprint([1] == [1], [1] is [1])  # True False', ['Calculations', 'Membership checks', 'Conditions'], [['Difference between == and is?', '== compares values; is checks whether two names refer to the same object.'], ['What does // do with negative numbers?', 'It floors the result, so -7 // 2 = -4.']], ['Check if a number is a power of two using bitwise &.']],
  ['conditions', 'Conditional Statements', 'Use if, elif and else to branch. Python treats 0, empty collections, None and "" as falsy. A conditional expression is written as a if cond else b. Python 3.10 adds match-case for structural pattern matching.', 'if cond:\n    ...\nelif other:\n    ...\nelse:\n    ...', 'marks = 78\nif marks >= 90:\n    grade = "A"\nelif marks >= 75:\n    grade = "B"\nelse:\n    grade = "C"\nprint(grade)\n\nstatus = "pass" if marks >= 40 else "fail"\nprint(status)\n\ncommand = "stop"\nmatch command:\n    case "start":\n        print("Starting")\n    case "stop":\n        print("Stopping")\n    case _:\n        print("Unknown")', ['Validation', 'Business rules', 'Menu programs'], [['What values are falsy in Python?', 'False, None, 0, 0.0, "", [], (), {}, set() and objects whose __bool__ returns False.'], ['Does Python have switch?', 'Not classic switch, but Python 3.10+ has match-case.']], ['Classify a triangle by its sides.', 'Check leap year.']],
  ['loops', 'Loops', 'for iterates over any iterable (range, list, string, dict); while repeats while a condition is true. break, continue and an optional else block (runs if the loop was not broken) are available. enumerate() gives indices; zip() iterates in parallel.', 'for i in range(start, stop, step):\n    ...\nwhile cond:\n    ...', 'total = sum(range(1, 11))\nprint("Sum:", total)\nfor i, name in enumerate(["Asha", "Dev"], start=1):\n    print(i, name)\nn = 29\nfor d in range(2, int(n ** 0.5) + 1):\n    if n % d == 0:\n        print("not prime")\n        break\nelse:\n    print("prime")         # runs only if no break happened', ['Iterating data', 'Retry loops', 'Pattern printing'], [['What does the else on a loop do?', 'It runs when the loop finishes normally, i.e. without hitting break.'], ['range(5) vs list(range(5))?', 'range is a lazy sequence object; list() materialises all values.']], ['Print the Fibonacci series up to n.', 'Find the sum of digits of a number.']],
  ['functions', 'Functions', 'Functions are defined with def and can have default, keyword, *args and **kwargs parameters. Functions are first-class objects: they can be passed around and returned. lambda creates small anonymous functions. Avoid mutable default arguments.', 'def name(a, b=2, *args, **kwargs):\n    return value\nsquare = lambda x: x * x', 'def greet(name, greeting="Hello"):\n    return f"{greeting}, {name}!"\n\ndef total(*nums):\n    return sum(nums)\n\ndef apply(fn, values):\n    return [fn(v) for v in values]\n\nprint(greet("Dev"), greet("Asha", greeting="Hi"))\nprint(total(1, 2, 3, 4))\nprint(apply(lambda x: x ** 2, [1, 2, 3]))\n\ndef fact(n):\n    return 1 if n <= 1 else n * fact(n - 1)\nprint(fact(10))', ['Reusable logic', 'Callbacks', 'Decorators'], [['What are *args and **kwargs?', '*args collects extra positional arguments into a tuple; **kwargs collects extra keyword arguments into a dict.'], ['Why avoid mutable default arguments?', 'The default object is created once and shared across calls, so changes persist between calls.']], ['Write a function returning the GCD.', 'Write a function that counts vowels.']],
  ['lists', 'Lists', 'A list is an ordered, mutable, dynamic array that can hold mixed types. Supports indexing (including negative), slicing, append, extend, insert, pop, remove, sort and reverse. Slicing creates a shallow copy.', 'nums = [1, 2, 3]\nnums.append(4); nums[-1]; nums[1:3]\nnums.sort(); sorted(nums, reverse=True)', 'marks = [72, 88, 95, 60]\nmarks.append(81)\nprint(max(marks), min(marks), sum(marks) / len(marks))\nprint(marks[::-1])           # reversed copy\nmarks.sort()\nprint(marks)\nmatrix = [[1, 2], [3, 4]]\nprint(matrix[1][0])\nunique = list(dict.fromkeys([3, 1, 3, 2, 1]))  # dedupe, keep order\nprint(unique)', ['Storing sequences', 'Stacks (append/pop)', 'Data processing'], [['Time complexity of list append and insert(0)?', 'append is amortised O(1); insert at the front is O(n).'], ['Shallow vs deep copy?', 'A shallow copy copies the outer list but shares inner objects; copy.deepcopy copies everything recursively.']], ['Rotate a list by k positions.', 'Find the second largest number.']],
  ['tuples', 'Tuples', 'A tuple is an ordered, immutable sequence. Tuples are hashable (if their items are), so they can be dict keys or set members. Tuple unpacking assigns multiple variables at once. Use them for fixed records and to return multiple values.', 't = (1, 2, 3)\nsingle = (5,)\na, b, c = t', 'point = (3, 4)\nx, y = point\nprint(x, y)\n\ndef min_max(values):\n    return min(values), max(values)   # returns a tuple\n\nlo, hi = min_max([4, 9, 1])\nprint(lo, hi)\ndistances = {(0, 0): "origin", (3, 4): "five away"}\nprint(distances[(3, 4)])\nprint(point.count(3), point.index(4))', ['Returning multiple values', 'Dictionary keys', 'Fixed records'], [['List vs tuple?', 'Lists are mutable; tuples are immutable, slightly faster and hashable.'], ['How do you create a one-element tuple?', 'With a trailing comma: (5,).']], ['Return the sum and average of a list as a tuple.']],
  ['sets', 'Sets', 'A set is an unordered collection of unique, hashable items with O(1) average membership tests. Supports union |, intersection &, difference - and symmetric difference ^.', 's = {1, 2, 3}\nempty = set()\ns.add(4); s.discard(2)\na | b; a & b; a - b', 'java_students = {"Asha", "Dev", "Kiran"}\npython_students = {"Dev", "Meera", "Kiran"}\nprint(java_students & python_students)   # both\nprint(java_students | python_students)   # either\nprint(java_students - python_students)   # only Java\nnums = [3, 1, 3, 2, 1]\nprint(len(set(nums)))                    # unique count', ['Removing duplicates', 'Fast membership checks', 'Comparing groups'], [['Why must set elements be hashable?', 'Sets use hash tables; elements must have a stable hash to be placed in buckets.'], ['How do you create an empty set?', 'set() — {} creates an empty dict.']], ['Find common elements in two lists.', 'Check if a string has all unique characters.']],
  ['dictionaries', 'Dictionaries', 'A dict maps unique, hashable keys to values with O(1) average lookups. Since Python 3.7, dicts preserve insertion order. Use get() for safe access, items() to iterate pairs, and collections.Counter/defaultdict for counting and grouping.', 'd = {"a": 1}\nd["b"] = 2\nd.get("c", 0)\nfor k, v in d.items(): ...', 'from collections import Counter, defaultdict\n\ntext = "to be or not to be"\nfreq = {}\nfor w in text.split():\n    freq[w] = freq.get(w, 0) + 1\nprint(freq)\nprint(Counter(text.split()).most_common(2))\n\ngroups = defaultdict(list)\nfor name in ["Asha", "Arun", "Dev"]:\n    groups[name[0]].append(name)\nprint(dict(groups))', ['Counting', 'Caching', 'JSON-like data'], [['How does a Python dict work internally?', 'It is a hash table: keys are hashed to find slots, with open addressing for collisions.'], ['dict[key] vs dict.get(key)?', 'dict[key] raises KeyError if missing; get returns None or a default.']], ['Count word frequency in a paragraph.', 'Group anagrams together.']],
  ['strings', 'Strings', 'Strings are immutable Unicode sequences. Useful methods: lower, upper, strip, split, join, replace, find, startswith, isdigit. f-strings format values. Use "".join(list) instead of += in loops for efficiency.', 's = "hello"\ns[0]; s[-1]; s[1:4]\n" ".join(words); s.split(",")\nf"{name} scored {marks:.1f}"', 's = "  BrainBridge Placement  "\nclean = s.strip()\nprint(clean.lower(), clean.split())\nprint(clean[::-1])\nprint(clean.count("e"), clean.find("Place"))\nword = "level"\nprint(word == word[::-1])          # palindrome check\nprint(", ".join(["Java", "Python", "C"]))\nprint(f"{3.14159:.2f}")', ['Text processing', 'Parsing', 'Formatting output'], [['Why use join instead of += in a loop?', 'Strings are immutable, so += creates a new string each time (O(n²) overall); join is O(n).'], ['What is string slicing s[::-1]?', 'A slice with step -1, producing the reversed string.']], ['Check if two strings are anagrams.', 'Capitalise the first letter of each word.']],
  ['comprehensions', 'Comprehensions', 'Comprehensions build lists, sets and dicts concisely: [expr for x in iterable if cond]. Generator expressions (x for x in ...) produce values lazily and save memory.', '[x * x for x in range(10) if x % 2 == 0]\n{k: v for k, v in pairs}\n(x for x in data)', 'squares = [x * x for x in range(1, 6)]\nevens = [x for x in range(20) if x % 2 == 0]\nlengths = {w: len(w) for w in ["java", "python", "c"]}\nunique_lengths = {len(w) for w in ["java", "python", "c"]}\nmatrix = [[i * j for j in range(1, 4)] for i in range(1, 4)]\ntotal = sum(x * x for x in range(1_000_000))  # generator: no big list in memory\nprint(squares, evens, lengths, unique_lengths, matrix, total, sep="\\n")', ['Data transformation', 'Filtering', 'Building lookup tables'], [['List comprehension vs generator expression?', 'A list comprehension builds the whole list in memory; a generator yields items one at a time lazily.'], ['Can comprehensions have multiple for clauses?', 'Yes, e.g. [(i, j) for i in a for j in b].']], ['Flatten a 2D list with a comprehension.', 'Create a dict of word → frequency with a comprehension.']],
  ['oop', 'Object-Oriented Programming', 'Python classes use __init__ to initialise objects and self to refer to the instance. Python supports inheritance (including multiple), method overriding, and polymorphism via duck typing. Special (dunder) methods like __str__ and __eq__ customise behaviour. Use @property for controlled attribute access and a single underscore for "internal" members.', 'class Name(Base):\n    def __init__(self, x):\n        self.x = x\n    def method(self):\n        ...', 'class Account:\n    def __init__(self, owner, balance=0):\n        self.owner = owner\n        self._balance = balance\n\n    @property\n    def balance(self):\n        return self._balance\n\n    def deposit(self, amount):\n        if amount <= 0:\n            raise ValueError("Amount must be positive")\n        self._balance += amount\n\n    def __str__(self):\n        return f"{self.owner}: {self._balance}"\n\nclass Savings(Account):\n    def add_interest(self, rate):\n        self.deposit(self.balance * rate / 100)\n\ns = Savings("Asha", 1000)\ns.add_interest(5)\nprint(s, s.balance)', ['Modelling domains', 'Frameworks (Django models)', 'Reusable components'], [['What is self?', 'A reference to the current instance, passed automatically as the first argument of instance methods.'], ['What is MRO?', 'Method Resolution Order: the order Python searches classes for a method, computed with C3 linearisation (see Class.__mro__).'], ['@staticmethod vs @classmethod?', 'staticmethod receives no implicit argument; classmethod receives the class (cls) and is often used as an alternate constructor.']], ['Create a Library class managing Book objects.', 'Implement __eq__ and __lt__ for a Student class.']],
  ['exceptions', 'Exception Handling', 'Errors are raised as exceptions and handled with try / except / else / finally. Catch specific exceptions, not bare except. raise re-raises or creates exceptions; custom exceptions subclass Exception. Context managers (with) handle cleanup.', 'try:\n    ...\nexcept (ValueError, ZeroDivisionError) as e:\n    ...\nelse:\n    ...\nfinally:\n    ...', 'class InsufficientFunds(Exception):\n    pass\n\ndef withdraw(balance, amount):\n    if amount > balance:\n        raise InsufficientFunds(f"Need {amount - balance} more")\n    return balance - amount\n\nfor value in ["10", "abc", "0"]:\n    try:\n        print(100 / int(value))\n    except ValueError:\n        print("Not a number:", value)\n    except ZeroDivisionError:\n        print("Cannot divide by zero")\n\ntry:\n    withdraw(50, 80)\nexcept InsufficientFunds as e:\n    print("Error:", e)', ['Input validation', 'Network/file errors', 'Clean APIs'], [['When does the else block of try run?', 'Only if no exception occurred in the try block.'], ['Why avoid bare except?', 'It also catches KeyboardInterrupt/SystemExit and hides bugs; catch specific exceptions.']], ['Safely read an integer from the user until valid.']],
  ['file-handling', 'File Handling', 'Use open() with a with statement so files close automatically. Modes: r, w (overwrite), a (append), b (binary), + (read/write). The csv and json modules handle common formats; pathlib offers an object-oriented path API.', 'with open("file.txt", "r", encoding="utf-8") as f:\n    data = f.read()', 'import json\nfrom pathlib import Path\n\npath = Path("students.txt")\npath.write_text("Asha,82\\nDev,74\\n", encoding="utf-8")\nwith open(path, encoding="utf-8") as f:\n    for line in f:\n        name, marks = line.strip().split(",")\n        print(name, int(marks))\n\nPath("data.json").write_text(json.dumps({"placed": True}))\nprint(json.loads(Path("data.json").read_text()))', ['Reading datasets', 'Logs', 'Config files'], [['Why use with open(...)?', 'It guarantees the file is closed even if an exception occurs.'], ['Difference between read(), readline() and readlines()?', 'read() returns the whole file; readline() one line; readlines() a list of all lines.']], ['Count the most common word in a file.', 'Convert a CSV file to JSON.']],
  ['modules', 'Modules and Packages', 'A module is a .py file; a package is a folder of modules (traditionally with __init__.py). Import with import, from ... import or aliases. if __name__ == "__main__": runs code only when the file is executed directly. pip installs third-party packages; virtual environments isolate dependencies.', 'import math\nfrom collections import Counter\nimport numpy as np\nif __name__ == "__main__":\n    main()', 'import math\nimport random\nfrom datetime import date\n\nprint(math.sqrt(144), math.factorial(5), math.gcd(12, 18))\nrandom.seed(1)\nprint(random.randint(1, 6))\nprint(date(2025, 1, 1).strftime("%A"))\n\ndef main():\n    print("Running as a script")\n\nif __name__ == "__main__":\n    main()', ['Organising projects', 'Reusing libraries', 'Packaging tools'], [['What does if __name__ == "__main__" do?', 'Runs the block only when the file is executed directly, not when imported.'], ['What is a virtual environment?', 'An isolated Python environment with its own packages (python -m venv venv).']], ['Split a program into two modules and import one from the other.']],
];

const C = [
  ['intro', 'Introduction to C', 'C is a procedural, compiled language close to the hardware. Programs are compiled (e.g. with gcc) into machine code. Every program starts at main(). C gives direct memory control through pointers, which makes it fast but requires care.', '#include <stdio.h>\nint main(void) {\n    return 0;\n}', '#include <stdio.h>\n\nint main(void) {\n    printf("Hello, BrainBridge!\\n");\n    return 0;\n}', ['Operating systems and drivers', 'Embedded systems', 'Compilers and databases'], [['What are the stages of compiling a C program?', 'Preprocessing → compilation → assembly → linking.'], ['Why does main return int?', 'The return value is the exit status; 0 means success.']], ['Compile with gcc main.c -o main and run it.']],
  ['variables', 'Variables and Data Types', 'C has basic types char, int, float, double with modifiers short, long, signed, unsigned. Sizes are platform-dependent; use sizeof to check. Uninitialised local variables contain garbage values. Format specifiers: %d, %ld, %f, %lf, %c, %s.', 'int a = 10;\nfloat f = 3.5f;\nchar c = \'A\';\nconst double PI = 3.14159;', '#include <stdio.h>\n\nint main(void) {\n    int age = 20;\n    double cgpa = 8.45;\n    char grade = \'A\';\n    unsigned int count = 4000000000u;\n    printf("%d %.2f %c %u\\n", age, cgpa, grade, count);\n    printf("int=%zu bytes, double=%zu bytes\\n", sizeof(int), sizeof(double));\n    int x = (int)9.8;   /* 9 */\n    printf("%d\\n", x);\n    return 0;\n}', ['Embedded variables with exact sizes', 'Low-level data handling'], [['What is the size of int in C?', 'Implementation-defined; commonly 4 bytes on modern 32/64-bit systems.'], ['What happens on signed integer overflow?', 'Undefined behaviour in C; unsigned overflow wraps around modulo 2^n.']], ['Read two integers with scanf and print their sum.']],
  ['operators', 'Operators', 'C supports arithmetic, relational, logical, bitwise, assignment, increment/decrement, conditional (?:), comma and sizeof operators. Integer division truncates. Expressions like i = i++ + ++i are undefined behaviour — avoid modifying a variable twice in one expression.', 'a + b; a % b; a & b; a << 2;\nmax = (a > b) ? a : b;', '#include <stdio.h>\n\nint main(void) {\n    int a = 17, b = 5;\n    printf("%d %d %.2f\\n", a / b, a % b, (double)a / b);\n    printf("%d\\n", a > b && b != 0);\n    printf("%d %d\\n", 6 & 3, 6 | 3);   /* 2 7 */\n    printf("%d\\n", 1 << 4);             /* 16 */\n    int n = 12;\n    printf("%s\\n", (n & 1) ? "odd" : "even");\n    return 0;\n}', ['Bit masks in embedded systems', 'Fast arithmetic'], [['What is the difference between & and &&?', '& is bitwise AND on each bit; && is logical AND that short-circuits.'], ['Why is i = i++ undefined?', 'The variable is modified twice without an intervening sequence point.']], ['Count set bits in an integer.', 'Swap two numbers using XOR.']],
  ['conditions', 'Conditional Statements', 'if, else if, else and switch control flow. In C, any non-zero value is true and 0 is false. switch works on integer types and needs break to avoid fall-through.', 'if (cond) { ... } else { ... }\nswitch (x) { case 1: ...; break; default: ...; }', '#include <stdio.h>\n\nint main(void) {\n    int marks = 78;\n    if (marks >= 90) printf("A\\n");\n    else if (marks >= 75) printf("B\\n");\n    else printf("C\\n");\n\n    char op = \'*\';\n    int a = 6, b = 3;\n    switch (op) {\n        case \'+\': printf("%d\\n", a + b); break;\n        case \'*\': printf("%d\\n", a * b); break;\n        default: printf("unknown\\n");\n    }\n    return 0;\n}', ['Menu-driven programs', 'Validation'], [['Can switch use strings in C?', 'No, only integer types (including char and enums).'], ['What is fall-through?', 'Without break, execution continues into the next case.']], ['Build a simple calculator with switch.']],
  ['loops', 'Loops', 'C has for, while and do-while loops, plus break and continue. A for loop has initialisation, condition and update parts, any of which may be empty (for(;;) is infinite).', 'for (int i = 0; i < n; i++) { ... }\nwhile (cond) { ... }\ndo { ... } while (cond);', '#include <stdio.h>\n\nint main(void) {\n    int n = 12345, rev = 0, sum = 0;\n    while (n > 0) {\n        int d = n % 10;\n        rev = rev * 10 + d;\n        sum += d;\n        n /= 10;\n    }\n    printf("reverse=%d digitsum=%d\\n", rev, sum);\n    for (int i = 1; i <= 4; i++) {\n        for (int j = 1; j <= i; j++) printf("%d ", j);\n        printf("\\n");\n    }\n    return 0;\n}', ['Iterating arrays', 'Number crunching', 'Pattern programs'], [['Which loop is guaranteed to run at least once?', 'do-while.'], ['What does continue do?', 'Skips the rest of the current iteration and moves to the next one.']], ['Check if a number is an Armstrong number.', 'Print Floyd\'s triangle.']],
  ['functions', 'Functions', 'Functions are declared with a return type, name and parameters; a prototype declares a function before use. C passes arguments by value — to modify a caller\'s variable, pass its address (pointer).', 'int add(int a, int b);        /* prototype */\nint add(int a, int b) { return a + b; }', '#include <stdio.h>\n\nint gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }\nvoid swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }\n\nint main(void) {\n    printf("%d\\n", gcd(48, 18));\n    int a = 3, b = 7;\n    swap(&a, &b);\n    printf("%d %d\\n", a, b);\n    return 0;\n}', ['Modular programs', 'Library design'], [['Call by value vs call by reference in C?', 'C is strictly call by value; passing a pointer simulates call by reference.'], ['Why are function prototypes needed?', 'So the compiler knows the parameter and return types before the function is called.']], ['Write a function to check primality.', 'Write a function to compute power(x, n).']],
  ['arrays', 'Arrays', 'An array stores elements of one type contiguously. Its size is fixed at declaration. Array names decay to a pointer to the first element when passed to functions, so the size must be passed separately. C does no bounds checking.', 'int a[5] = {1, 2, 3, 4, 5};\nint grid[3][4];\nint n = sizeof(a) / sizeof(a[0]);', '#include <stdio.h>\n\nint max_of(const int arr[], int n) {\n    int m = arr[0];\n    for (int i = 1; i < n; i++) if (arr[i] > m) m = arr[i];\n    return m;\n}\n\nint main(void) {\n    int marks[] = {72, 88, 95, 60};\n    int n = sizeof(marks) / sizeof(marks[0]);\n    printf("max=%d\\n", max_of(marks, n));\n    int m[2][2] = {{1, 2}, {3, 4}};\n    printf("%d\\n", m[1][0]);\n    return 0;\n}', ['Buffers', 'Matrices', 'Lookup tables'], [['What happens if you access an array out of bounds in C?', 'Undefined behaviour: it may crash or silently corrupt memory.'], ['Why pass the size with an array?', 'Inside the function the array is just a pointer, so sizeof no longer gives the array size.']], ['Find the frequency of each element.', 'Multiply two matrices.']],
  ['strings', 'Strings', 'A C string is a char array terminated by \'\\0\'. string.h provides strlen, strcpy, strncpy, strcat, strcmp, strchr and strstr. Always leave space for the terminator and prefer bounded functions to avoid buffer overflows.', 'char s[20] = "hello";\nstrlen(s); strcmp(a, b); strcpy(dest, src);', '#include <stdio.h>\n#include <string.h>\n#include <ctype.h>\n\nint main(void) {\n    char s[] = "level";\n    int n = strlen(s), ok = 1;\n    for (int i = 0; i < n / 2; i++) if (s[i] != s[n - 1 - i]) ok = 0;\n    printf("%s is %spalindrome\\n", s, ok ? "a " : "not a ");\n    char name[20];\n    strcpy(name, "brain");\n    strcat(name, "bridge");\n    for (int i = 0; name[i]; i++) name[i] = toupper((unsigned char)name[i]);\n    printf("%s %d\\n", name, strcmp("abc", "abd") < 0);\n    return 0;\n}', ['Parsing input', 'Text protocols'], [['Why is the null terminator needed?', 'String functions find the end of the string by scanning for \'\\0\'.'], ['Why is gets() unsafe?', 'It cannot limit input length and can overflow the buffer; use fgets instead.']], ['Count words in a sentence.', 'Reverse a string in place.']],
  ['pointers', 'Pointers', 'A pointer stores a memory address. & gives the address of a variable; * dereferences a pointer. Pointer arithmetic moves by the size of the pointed type. NULL means "points nowhere". Pointers enable dynamic memory, efficient array handling and linked data structures.', 'int x = 5;\nint *p = &x;\n*p = 10;     /* x becomes 10 */\nint **pp = &p;', '#include <stdio.h>\n\nint main(void) {\n    int arr[] = {10, 20, 30};\n    int *p = arr;                 /* same as &arr[0] */\n    printf("%d %d\\n", *p, *(p + 2));\n    p++;\n    printf("%d\\n", *p);           /* 20 */\n    int x = 5, *q = &x, **qq = &q;\n    **qq = 99;\n    printf("x=%d\\n", x);\n    return 0;\n}', ['Dynamic data structures', 'Passing large data efficiently', 'Hardware access'], [['What is a dangling pointer?', 'A pointer to memory that has been freed or gone out of scope.'], ['Difference between int *p and int p[]?', 'p[] declares an array with storage; *p is a variable holding an address. As parameters both mean pointer.'], ['What is a void pointer?', 'A generic pointer that can hold any address but must be cast before dereferencing.']], ['Find the sum of an array using pointer arithmetic.', 'Swap two strings using pointers to pointers.']],
  ['structures', 'Structures', 'A struct groups variables of different types under one name. Access members with . (on a struct) or -> (on a pointer to a struct). typedef creates shorter type names. Structures are the basis for linked lists, trees and records.', 'struct Student { char name[20]; int marks; };\ntypedef struct { int x, y; } Point;\np->x; s.marks;', '#include <stdio.h>\n#include <string.h>\n\ntypedef struct {\n    char name[20];\n    int marks;\n} Student;\n\nvoid bonus(Student *s) { s->marks += 5; }\n\nint main(void) {\n    Student list[2] = {{"Asha", 80}, {"Dev", 70}};\n    bonus(&list[1]);\n    for (int i = 0; i < 2; i++) printf("%s %d\\n", list[i].name, list[i].marks);\n    printf("size=%zu\\n", sizeof(Student));\n    return 0;\n}', ['Records', 'Linked lists, trees', 'Packets and file headers'], [['What is structure padding?', 'The compiler inserts unused bytes so members are aligned, which can make sizeof(struct) larger than the sum of members.'], ['. vs -> ?', '. accesses a member of a struct variable; -> accesses a member through a pointer.']], ['Store and sort 5 students by marks.']],
  ['unions', 'Unions', 'A union is like a struct, but all members share the same memory, so its size equals the largest member. Only one member holds a meaningful value at a time. Unions save memory and are used for type punning and tagged variants.', 'union Data { int i; float f; char c; };', '#include <stdio.h>\n\nunion Value { int i; float f; char bytes[4]; };\n\nint main(void) {\n    union Value v;\n    v.i = 65;\n    printf("i=%d\\n", v.i);\n    v.f = 2.5f;              /* overwrites the same memory */\n    printf("f=%.1f size=%zu\\n", v.f, sizeof(union Value));\n    return 0;\n}', ['Embedded protocols', 'Memory-efficient variants'], [['Struct vs union?', 'Struct members have separate memory (size ≈ sum); union members overlap (size = largest member).'], ['When would you use a union?', 'When a variable can hold one of several types at a time, e.g. a tagged value in an interpreter.']], ['Create a tagged union that stores either an int or a float.']],
  ['dynamic-memory', 'Dynamic Memory Allocation', 'malloc, calloc, realloc and free (from stdlib.h) manage heap memory at runtime. Always check for NULL, free what you allocate exactly once, and set freed pointers to NULL to avoid dangling pointers. Forgetting free causes memory leaks.', 'int *a = malloc(n * sizeof(int));\nint *b = calloc(n, sizeof(int));\na = realloc(a, 2 * n * sizeof(int));\nfree(a);', '#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    int n = 5;\n    int *a = malloc(n * sizeof *a);\n    if (!a) return 1;\n    for (int i = 0; i < n; i++) a[i] = i * i;\n    int *bigger = realloc(a, 2 * n * sizeof *a);\n    if (!bigger) { free(a); return 1; }\n    a = bigger;\n    for (int i = n; i < 2 * n; i++) a[i] = i * i;\n    for (int i = 0; i < 2 * n; i++) printf("%d ", a[i]);\n    printf("\\n");\n    free(a);\n    a = NULL;\n    return 0;\n}', ['Variable-size data', 'Linked structures', 'Buffers'], [['malloc vs calloc?', 'malloc leaves memory uninitialised; calloc zero-initialises and takes count and size separately.'], ['What is a memory leak?', 'Allocated memory that is never freed and can no longer be reached.']], ['Read n numbers into a dynamically allocated array.', 'Implement a growable array with realloc.']],
  ['recursion', 'Recursion', 'A recursive function calls itself on a smaller input until it reaches a base case. Each call uses stack space; deep recursion can overflow the stack. Many problems (trees, divide and conquer, backtracking) are naturally recursive.', 'int f(int n) {\n    if (n == 0) return base;\n    return combine(f(n - 1));\n}', '#include <stdio.h>\n\nlong fib(int n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }\nvoid hanoi(int n, char from, char to, char via) {\n    if (n == 0) return;\n    hanoi(n - 1, from, via, to);\n    printf("Move disk %d %c->%c\\n", n, from, to);\n    hanoi(n - 1, via, to, from);\n}\n\nint main(void) {\n    printf("%ld\\n", fib(10));\n    hanoi(3, \'A\', \'C\', \'B\');\n    return 0;\n}', ['Tree traversal', 'Divide and conquer', 'Backtracking'], [['What happens without a base case?', 'Infinite recursion until the stack overflows.'], ['Recursion vs iteration?', 'Recursion is often clearer for recursive structures; iteration avoids call overhead and stack limits.']], ['Sum digits recursively.', 'Print all permutations of a string.']],
  ['file-handling', 'File Handling', 'Files are accessed through FILE * using fopen, fprintf/fscanf, fgets/fputs, fread/fwrite and fclose. Modes: "r", "w", "a", with "b" for binary and "+" for update. Always check that fopen did not return NULL.', 'FILE *fp = fopen("data.txt", "r");\nif (!fp) { perror("open"); }\nfclose(fp);', '#include <stdio.h>\n\nint main(void) {\n    FILE *fp = fopen("marks.txt", "w");\n    if (!fp) { perror("fopen"); return 1; }\n    fprintf(fp, "Asha 82\\nDev 74\\n");\n    fclose(fp);\n\n    fp = fopen("marks.txt", "r");\n    if (!fp) { perror("fopen"); return 1; }\n    char name[20]; int m, total = 0;\n    while (fscanf(fp, "%19s %d", name, &m) == 2) { printf("%s %d\\n", name, m); total += m; }\n    fclose(fp);\n    printf("total=%d\\n", total);\n    return 0;\n}', ['Saving program data', 'Log files', 'Binary formats'], [['Text mode vs binary mode?', 'Text mode may translate newlines on some platforms; binary mode reads/writes bytes exactly.'], ['What does fseek do?', 'Moves the file position indicator to a given offset.']], ['Copy a file character by character.', 'Count lines in a text file.']],
  ['storage-classes', 'Storage Classes', 'Storage classes define scope, lifetime and linkage: auto (default for locals), register (hint for fast access), static (keeps value between calls; file-scope static limits linkage to the file) and extern (declares a variable defined elsewhere).', 'static int count = 0;\nextern int shared;\nregister int i;', '#include <stdio.h>\n\nint counter(void) {\n    static int calls = 0;   /* initialised once, keeps its value */\n    return ++calls;\n}\n\nint main(void) {\n    counter(); counter();\n    printf("calls=%d\\n", counter());   /* 3 */\n    return 0;\n}', ['Counters across calls', 'Module-private globals', 'Sharing globals across files'], [['What is a static local variable?', 'A local variable with static lifetime: it is initialised once and retains its value between calls.'], ['What does extern do?', 'Declares a variable defined in another translation unit without allocating storage.']], ['Use a static variable to count how many times a function runs.']],
  ['preprocessor', 'Preprocessor Directives', 'The preprocessor runs before compilation. #include inserts files, #define creates macros, and #if/#ifdef/#ifndef enable conditional compilation. Include guards prevent double inclusion. Macros are text substitution, so parenthesise arguments.', '#include <stdio.h>\n#define MAX 100\n#define SQUARE(x) ((x) * (x))\n#ifndef HEADER_H\n#define HEADER_H\n#endif', '#include <stdio.h>\n#define SQUARE(x) ((x) * (x))\n#define BAD_SQUARE(x) x * x\n#define DEBUG 1\n\nint main(void) {\n    printf("%d %d\\n", SQUARE(2 + 3), BAD_SQUARE(2 + 3));  /* 25 vs 11 */\n#if DEBUG\n    printf("debug build, compiled on %s\\n", __DATE__);\n#endif\n    return 0;\n}', ['Configuration flags', 'Header guards', 'Platform-specific code'], [['Macro vs function?', 'Macros are expanded textually (no type checking, no call overhead); functions are type-checked and evaluated once per argument.'], ['What is an include guard?', '#ifndef/#define/#endif around a header to prevent multiple inclusion.']], ['Write a MAX(a, b) macro and show why parentheses matter.']],
];

function toTopics(list, lang) {
  return list.map(([slug, title, explanation, syntax, example, apps, iq, practice], i) => ({
    slug, title, summary: explanation.split('. ')[0] + '.', sort: i,
    lesson: {
      title, difficulty: i < 6 ? 'easy' : i < 12 ? 'medium' : 'hard', minutes: 25,
      content: {
        explanation, syntax, syntax_language: lang,
        code: { [lang]: example },
        applications: apps,
        interview_questions: iq.map(([q, a]) => ({ question: q, answer: a })),
        practice,
      },
    },
  }));
}

module.exports = {
  java: toTopics(JAVA, 'java'),
  python: toTopics(PYTHON, 'python'),
  c: toTopics(C, 'c'),
};
